import copy
import hashlib
import json
import os


class ConflictError(Exception):
    pass


def _matches(row, where):
    for key, value in where.items():
        if key not in row or row[key] != value:
            return False
    return True


class Database:
    def __init__(self, path=None):
        self._path = os.fspath(path) if path is not None else None
        self._tables = {}
        self._versions = {}
        self._version = 0
        self._next_id = 1
        self._closed = False

        if self._path is not None:
            parent = os.path.dirname(os.path.abspath(self._path))
            if parent:
                os.makedirs(parent, exist_ok=True)
            self._load()

    def _load(self):
        if self._path is None or not os.path.exists(self._path):
            return

        with open(self._path, "rb") as f:
            data = f.read()

        offset = 0
        total = len(data)

        while offset < total:
            newline = data.find(b"\n", offset)
            if newline == -1:
                raw = data[offset:]
                next_offset = total
            else:
                raw = data[offset:newline]
                next_offset = newline + 1

            if raw.strip():
                try:
                    text = raw.decode("utf-8")
                    outer = json.loads(text)

                    if not isinstance(outer, dict):
                        raise ValueError

                    payload = outer.get("r")
                    digest = outer.get("h")

                    if not isinstance(payload, dict) or not isinstance(digest, str):
                        raise ValueError

                    body = json.dumps(
                        payload,
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    )

                    if hashlib.sha256(body.encode("utf-8")).hexdigest() != digest:
                        raise ValueError

                    self._apply_record(payload)
                except Exception:
                    # Повреждённый хвост отбрасываем, чтобы следующие
                    # commit-ы можно было безопасно дописывать в файл.
                    self._truncate_to(offset)
                    break

            offset = next_offset

    def _truncate_to(self, offset):
        if self._path is None:
            return
        with open(self._path, "r+b") as f:
            f.truncate(offset)
            f.flush()
            os.fsync(f.fileno())

    def _apply_record(self, rec):
        kind = rec.get("t")

        if kind == "a":
            ident = rec.get("id")
            if not isinstance(ident, int) or isinstance(ident, bool) or ident < 1:
                raise ValueError
            if ident + 1 > self._next_id:
                self._next_id = ident + 1

        elif kind == "c":
            ops = rec.get("ops")
            if not isinstance(ops, list):
                raise ValueError

            version = self._version + 1
            for op in ops:
                self._apply_op(op, version, strict=True)
            self._version = version

        else:
            raise ValueError

    def _apply_op(self, op, version, strict=False):
        if not isinstance(op, dict):
            raise ValueError

        kind = op.get("o")
        table = op.get("table")
        ident = op.get("id")

        if not isinstance(table, str):
            raise ValueError
        if not isinstance(ident, int) or isinstance(ident, bool) or ident < 1:
            raise ValueError

        if kind in ("i", "u"):
            row = op.get("row")
            if not isinstance(row, dict):
                raise ValueError
            if row.get("_id") != ident:
                raise ValueError

            if strict and kind == "u":
                if table not in self._tables or ident not in self._tables[table]:
                    raise ValueError

            self._tables.setdefault(table, {})[ident] = copy.deepcopy(row)
            self._versions.setdefault(table, {})[ident] = version

            if kind == "i" and ident + 1 > self._next_id:
                self._next_id = ident + 1

        elif kind == "d":
            if strict:
                if table not in self._tables or ident not in self._tables[table]:
                    raise ValueError

            self._tables.get(table, {}).pop(ident, None)
            self._versions.get(table, {}).pop(ident, None)

        else:
            raise ValueError

