        if self._path is None:
            return
        if self._closed:
            raise RuntimeError("database is closed")

        body = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        digest = hashlib.sha256(body.encode("utf-8")).hexdigest()

        outer = {"r": payload, "h": digest}
        line = json.dumps(
            outer,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ) + "\n"

        with open(self._path, "ab") as f:
            f.write(line.encode("utf-8"))
            f.flush()
            os.fsync(f.fileno())

