        ident = self._next_id
        self._next_id += 1
        return ident

    def begin(self):
        if self._closed:
            raise RuntimeError("database is closed")
        return Transaction(self)

    def close(self):
        self._closed = True


class Transaction:
    def __init__(self, db):
