        stored["_id"] = ident

        self._tables.setdefault(table, {})[ident] = stored
        self._inserted.add((table, ident))
        self._ops.append({
            "o": "i",
            "table": table,
            "id": ident,
            "row": copy.deepcopy(stored),
        })

        return ident

